// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Attacker attacker;

    function setUp() public { c = new SimpleWallet(); attacker = new Attacker(); }

    function testFuzz_property(uint256 fundAmount, uint256 sendValue) public {
        fundAmount = bound(fundAmount, 1 wei, 1 ether);
        sendValue = bound(sendValue, 0 wei, fundAmount);

        vm.deal(address(this), 0);
        vm.deal(address(attacker), fundAmount);
        vm.deal(address(c), fundAmount);

        vm.prank(address(attacker));
        bool ok;
        try c.sendMoney(address(attacker), sendValue, "") {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceBefore = address(c).balance;

        uint256 withdrawAmount = balanceBefore;
        vm.prank(address(attacker));
        try c.withdraw(withdrawAmount) {
        } catch {
        }

        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceAfter == balanceBefore);
    }
}

contract Attacker {
    receive() external payable {}
}
